/* @author MILO-GAO(高振銘)@2020 */ package page2020.unit;import page2020.core.Bean;public class Icon extends Bean<Icon> {	public static final class ValueOfSize {		public static final String icon32 = "32x32";		public static final String icon48 = "48x48";		public static final String icon192 = "192x192";		public static final String apple = "180x180";	}	private String rel;	private String type;	private String size;	private String href;	public Icon(String filename, String size) {		if (size.equals(ValueOfSize.apple)) {			this.rel = "apple-touch-icon-precomposed";		} else {			this.rel = "shortcut icon";		}		int pos = filename.lastIndexOf(".");		if (pos > 0) {			this.type = filename.substring(pos + 1).toLowerCase();		} else {			this.type = "png";		}		this.size = size;		this.href = filename;	}	public String getRel() {		return rel;	}	public void setRel(String rel) {		this.rel = rel;	}	public String getType() {		return type;	}	public void setType(String type) {		this.type = type;	}	public String getSize() {		return size;	}	public void setSize(String size) {		this.size = size;	}	public String getHref() {		return href;	}	public void setHref(String href) {		this.href = href;	}	}